def get_size_range_index(basic_size: float) -> int:
    """根据基本尺寸查找对应的尺寸段索引"""
    for i, (low, high) in enumerate(SIZE_RANGES):
        if basic_size == 0 and low == 0:
            if basic_size <= high:
                return i
        elif low < basic_size <= high:
            return i
    return -1  # 超出范围


def get_it_tolerance(basic_size: float, it_grade: str) -> float:
    """
    查询标准公差值
    
    Args:
        basic_size: 基本尺寸 (mm)
        it_grade: IT公差等级 (如 "IT7", "H7" 中的 7)
    
    Returns:
        公差值 (μm), 超出范围返回 -1
    """
    # 处理等级字符串
    grade = it_grade.upper().replace("IT", "")
    key = "IT" + grade
    if key not in IT_GRADES:
        return -1

    grade_idx = IT_GRADES.index(key)  # IT01/IT0 占前两列, 不能直接 int()
    size_idx = get_size_range_index(basic_size)

    if size_idx == -1:
        return -1

    v = IT_VALUES[size_idx][grade_idx]
    return -1 if v is None else v  # None = 该等级无规定值 (如 IT01/IT0 >500mm)


def get_size_range_label(basic_size: float) -> str:
    """获取基本尺寸对应的分段标签"""
    idx = get_size_range_index(basic_size)
    if idx == -1:
        return "超出范围"
    low, high = SIZE_RANGES[idx]
    if low == 0:
        return f"0~{high}mm"
    return f"{low}~{high}mm"


def get_available_grades_for_size(basic_size: float) -> list:
    """获取某尺寸段可用的公差等级"""
    return IT_GRADES
